        _scoreAxes(finalCash, finalRep, finalMission, totalPlacements, dec){dec=dec||{};var cashScore=this._clamp(finalCash/700*100,0,100);var sh4=this._shares(4,dec);var maxs=Math.max.apply(null,sh4);var divScore=maxs<=0.40?this._clamp((0.30-maxs)/0.10*40+60,0,100):25;var gov=dec.governance?100:50;var qCost=200+1.45*(dec.studentsKept||580);var ef=dec.emergencyFund?55+45*this._clamp(finalCash/qCost,0,1):55;var sustain=0.55*cashScore+0.20*divScore+0.15*gov+0.10*ef;var placeScore=this._clamp(totalPlacements/340*100,0,100);var rigor=dec.rigor?100:55;var cohort=this._clamp(((dec.studentsKept||580)-200)/380*100,0,100);var impact=0.28*placeScore+0.25*finalMission+0.22*finalRep+0.13*rigor+0.12*cohort;if(finalRep<35)impact=Math.min(impact,50);if(finalMission<50)impact=Math.min(impact,55);var gr=(dec.guardrail!=null)?dec.guardrail:65;if(finalMission<70||finalMission<gr)impact=Math.min(impact,70);var performance='Needs Improvement';if(sustain>=45&&impact>=45)performance='Good';if(sustain>=60&&impact>=60)performance='Excellent';if(sustain>=75&&impact>=75)performance='Outstanding';return {sustain:sustain,impact:impact,overall:Math.min(sustain,impact),performance:performance};}
        _tierLabel(id) {
            var es = this._lang() === 'es';
            var m = es ? { outstanding: 'Sobresaliente', excellent: 'Excelente', good: 'Buena', needs_improvement: 'Necesita mejorar' }
                       : { outstanding: 'Outstanding', excellent: 'Excellent', good: 'Good', needs_improvement: 'Needs Improvement' };
            return m[id] || m.needs_improvement;
        }
        formatCompletionMessage(summary) {
            summary = summary || {};
            var es = this._lang() === 'es';
            var ov = (typeof summary.overallScore === 'number') ? summary.overallScore : Math.min(summary.sustainabilityScore || 0, summary.impactScore || 0);
            var ids = { 'Outstanding': 'outstanding', 'Excellent': 'excellent', 'Good': 'good', 'Needs Improvement': 'needs_improvement' };
            var perfL = this._tierLabel(ids[summary.performance] || summary.performance);
            var sus = summary.sustainabilityScore || 0, imp = summary.impactScore || 0;
            var ins = summary.insights || [], qs = summary.discussionQuestions || [];
            var color = ov >= 75 ? '#2e7d32' : (ov >= 60 ? '#43a047' : (ov >= 45 ? '#f9a825' : '#c62828'));
