            h += '<p style="font-weight:600;color:' + color + ';margin:2px 0;">' + perfL + '</p>';
            h += '<p class="text-muted" style="margin-bottom:6px;">' + (es ? 'Sostenibilidad' : 'Sustainability') + ': ' + sus + ' · ' + (es ? 'Impacto' : 'Impact') + ': ' + imp + '</p>';
            h += '<div style="text-align:left;display:inline-block;max-width:44rem;">';
            if (summary.turningPoint) h += '<p style="margin-top:12px;"><strong>' + (es ? 'Punto de giro' : 'Turning point') + ':</strong> ' + summary.turningPoint + '</p>';
            if (ins.length) h += '<p style="margin:10px 0 2px;"><strong>' + (es ? 'Lo que pasó en tu partida' : 'What happened in your run') + '</strong></p><ul>' + ins.map(li).join('') + '</ul>';
            if (qs.length) h += '<p style="margin:10px 0 2px;"><strong>' + (es ? 'Para discutir en clase' : 'For class discussion') + '</strong></p><ul>' + qs.map(li).join('') + '</ul>';
            h += '</div><hr class="my-3"><p class="text-muted">' + (es ? 'Gracias por participar.' : 'Thank you for participating.') + '</p></div>';
