        }
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 400,
                    reputation: 55,
                    mission: 90,
                    students: 580,
                    corporatePartners: 3,
                    totalPlacements: 0,
                    mfLost: false,
                    baseByPeriod: {},
                    cashHistory: [],
                    reputationHistory: [],
                    missionHistory: [],
                    placementsHistory: [],
                    revenueHistory: [],
                    costHistory: []
                };
            }
            if (!state.domainState.baseByPeriod) state.domainState.baseByPeriod = {};
            // No pre-filled decisions: the view holds the starting values, and the model reads a decision only from
            // the round it is taken in, so an undo of round 1 cannot restore stale defaults over the player's inputs
            if (!state.decisions) state.decisions = {};
            this._updatePanels(state.currentPeriod || 1);
            this._updateBriefing(state);
            this._updateAllocDisplays();
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var period = sim.state.currentPeriod;
            function val(id) { var e = document.getElementById(id); return e ? e.value : null; }
            function num(id, def) { var v = val(id); return v != null ? (parseInt(v) || 0) : def; }
            function chk(id) { var e = document.getElementById(id); return e ? !!e.checked : false; }
            function warn(k) { sim.uiManager.showNotification(sim.t(k), 'warning'); }
            var self = this;

            if (period === 1) {
                decisions.studentsKept = num('studentsInput', 580);
                decisions.honest = chk('honestInput');
                if (decisions.studentsKept < 200 || decisions.studentsKept > 580) { warn('students_warning'); return false; }
            } else if (period === 2) {
                var m = [num('mixGrants', 0), num('mixCorp', 0), num('mixAlianza', 0), num('mixPlace', 0), num('mixIndiv', 0)];
                if (m.reduce(function(a, b) { return a + b; }, 0) !== 100) { warn('alloc_warning'); return false; }
                decisions.mix = m;
                decisions.paidBootcamp = self._clamp(num('bootcampInput', 0), 0, 100);
                decisions.guardrail = self._clamp(num('guardrailInput', 70), 40, 90);
            } else if (period === 3) {
                decisions.retainMF = chk('retainMFInput');
                decisions.transparent = chk('transparentInput');
                decisions.governance = chk('governanceInput');
            } else if (period === 4) {
                var m4 = [num('mix4Grants', 0), num('mix4Corp', 0), num('mix4Alianza', 0), num('mix4Place', 0), num('mix4Indiv', 0)];
                if (m4.reduce(function(a, b) { return a + b; }, 0) !== 100) { warn('alloc_warning'); return false; }
                decisions.mix4 = m4;
                decisions.emergencyFund = chk('emergencyFundInput');
                decisions.rigor = chk('rigorInput');
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var idx = period - 1;

            if (!ds.baseByPeriod) ds.baseByPeriod = {};
            var pk = String(period);
            if (!ds.baseByPeriod[pk]) {
                ds.baseByPeriod[pk] = {
                    cash: ds.cash, rep: ds.reputation, mission: ds.mission,
                    partners: ds.corporatePartners, placements: ds.totalPlacements, mfLost: ds.mfLost
                };
            }
            var base = ds.baseByPeriod[pk];

            var students = (d.studentsKept != null) ? d.studentsKept : 580;
            var sh = this._shares(period, d);
            var honest = !!d.honest;
            var cred = base.rep;

            // Decisions not yet taken read as the status quo, never as whatever the decisions object holds (undo safe)
            var retainNow = (period >= 3) ? !!d.retainMF : true;
            var mfLost = base.mfLost || (period >= 3 && !retainNow);
            var rate = (retainNow && !mfLost) ? 0.60 : 0.42;
            var placementsQ = Math.round(students * rate * 0.25);

            var grants = POT.g * this._emph(sh[0]) * (cred / 55) * USAID_CUT;
            var govNow = (period >= 3) && !!d.governance;
            if (govNow) grants += 150;                                               // the foundation renews
            var corp = POT.c * this._emph(sh[1]) * (base.rep / 55) * (1 + 0.08 * base.partners);
            var alianza = POT.a * this._emph(sh[2]);
            var place = (POT.p + 0.9 * placementsQ) * this._emph(sh[3]);
            var indiv = POT.i * this._emph(sh[4]) * (base.rep / 55);

            var intensity = (period >= 2) ? (d.paidBootcamp || 0) : 40;              // bank bootcamp; Round 1 keeps the shipped default of 40
            var paid = 4.5 * intensity;
            var mission = this._clamp(90 - 0.5 * intensity, 0, 100);
            var guardrail = (period >= 2) ? ((d.guardrail != null) ? d.guardrail : 70) : 65;
            // Drift: places fall below the line social funders accept (70), or below the public guardrail FDI set.
            // A low guardrail no longer hides drift; a guardrail that is breached counts as drift too.
            var drift = (mission < 70) || (mission < guardrail);
            if (drift) { grants *= 0.6; indiv *= 0.6; }                              // social funders flee mission drift

            var scandalRep = 0;
            if (period === 3) {                                                      // the journalist story resolves
                var tr = !!d.transparent;
                if (honest) { scandalRep = tr ? 4 : -4; }
                else { scandalRep = tr ? -14 : -28; grants *= 0.7; corp *= 0.85; }
            }

            var revenue = grants + corp + alianza + place + indiv + paid;
            var opCost = 200 + 1.45 * students;
            var oneTime = 0;
            if (period === 3 && retainNow) oneTime += 40;
            if (period === 3 && govNow) oneTime += 85;
            if (period === 4 && d.rigor) oneTime += 60;
            var cost = opCost + oneTime;
            var net = revenue - cost;

            var cash = base.cash + net;
            var partners = base.partners + ((sh[1] >= 0.20) ? 1 : 0);
            var placementsTot = base.placements + placementsQ;

            var rd = (net > 0 ? 2 : -5) + (honest ? 3 : -2);
            if (govNow && period === 3) rd += 4;
            if (d.rigor && period === 4) rd += 5;
            if (drift) rd -= 8;
            if (period >= 3 && mfLost && !retainNow) rd -= 4;
