            ds.reputation = rep;
            ds.mission = mission;
            ds.students = students;
            ds.corporatePartners = partners;
            ds.totalPlacements = placementsTot;
            ds.mfLost = mfLost;

            ds.cashHistory = ds.cashHistory.slice(0, idx); ds.cashHistory.push(Math.round(cash));
            ds.reputationHistory = ds.reputationHistory.slice(0, idx); ds.reputationHistory.push(Math.round(rep));
            ds.missionHistory = ds.missionHistory.slice(0, idx); ds.missionHistory.push(Math.round(mission));
            ds.placementsHistory = ds.placementsHistory.slice(0, idx); ds.placementsHistory.push(placementsQ);
            ds.revenueHistory = ds.revenueHistory.slice(0, idx); ds.revenueHistory.push(Math.round(revenue));
            ds.costHistory = ds.costHistory.slice(0, idx); ds.costHistory.push(Math.round(cost));
            // Provisional score: decisions of later rounds read as the shipped defaults until they are taken
            var sd = {
                studentsKept: students,
                governance: (period >= 3) ? !!d.governance : true,
                emergencyFund: (period >= 4) ? !!d.emergencyFund : true,
                rigor: (period >= 4) ? !!d.rigor : true,
                guardrail: guardrail,
                mix4: (period >= 4 && d.mix4) ? d.mix4 : [22, 22, 20, 20, 16]
