            ds.score = __ov;
            ds.performance = { overallScore: __ov, sustainabilityScore: Math.round(__ax.sustain), impactScore: Math.round(__ax.impact), grade: __ax.performance };


            this._scheduleBriefingRefresh();

            return {
                period: period,
                revenue: Math.round(revenue),
                cost: Math.round(cost),
                net: Math.round(net),
                cash: Math.round(cash),
                reputation: Math.round(rep),
                mission: Math.round(mission),
                placementsQ: placementsQ,
                maxShare: ms,
                drift: drift,
                crisisChannel: null,
                overallScore: __ov,
                score: __ov
            };
        }

