            var dec = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.decisions : {};
            var last = history[history.length - 1].results || {};
            var finalCash = last.cash || 0, finalRep = last.reputation || 0, finalMission = last.mission || 0;
            var totalPlacements = history.reduce(function(s, r) { return s + (r.results ? r.results.placementsQ || 0 : 0); }, 0);

            var sh4 = this._shares(4, dec); var maxs = Math.max.apply(null, sh4);
            var __ax = this._scoreAxes(finalCash, finalRep, finalMission, totalPlacements, dec);
            var sustain = __ax.sustain, impact = __ax.impact, performance = __ax.performance;

            var __es = this._lang() === 'es';
            var L = function(en, es) { return __es ? es : en; };
            var kept = (dec.studentsKept != null) ? dec.studentsKept : 580;
            var mixR2 = dec.mix || [24, 22, 20, 18, 16];
            var tot2 = mixR2.reduce(function(a, b) { return a + b; }, 0) || 1;
            var g2 = Math.round(mixR2[0] / tot2 * 100), max2 = Math.round(Math.max.apply(null, mixR2) / tot2 * 100);
            var gr = (dec.guardrail != null) ? dec.guardrail : 65;
            var fm = Math.round(finalMission);
            // Mistakes of this situation (teaching.mistakes), detected from the decisions actually taken
            var named = [];
            if (dec.honest === false) named.push({ r: 1, t: L('Headline figure kept: FDI stood behind 72% when its own audit said 52%, and the journalist’s story turned that gap into lost credibility with funders.', 'Cifra de titular mantenida: FDI defendió el 72% cuando su propia auditoría decía 52%, y el reportaje convirtió esa brecha en credibilidad perdida ante los financiadores.') });
            if (kept <= 300) named.push({ r: 1, t: L('Deep cut to be safe: keeping ' + kept + ' students protected cash, but placements and the cohort carry the impact side of the year, and the board judges both.', 'Recorte profundo por seguridad: mantener ' + kept + ' estudiantes protegió la caja, pero las colocaciones y la cohorte sostienen el lado del impacto del año, y la junta juzga ambos.') });
            if (g2 > 30 && g2 >= max2) named.push({ r: 2, t: L('Mix rebuilt around grants: competitive grants were your largest stream (' + g2 + '%), the very stream the cut had just shrunk.', 'Mezcla reconstruida sobre subvenciones: las subvenciones concursables fueron tu mayor canal (' + g2 + '%), justo el canal que el recorte acababa de reducir.') });
            if (fm < 70 && gr < 70) named.push({ r: 2, t: L('Guardrail that did not bind: a public commitment of ' + gr + '% let the bootcamp take mission integrity to ' + fm + '%, below the 70% social funders expect, and they pulled back.', 'Salvaguarda que no oblig\u00f3: un compromiso público del ' + gr + '% dejó que el bootcamp llevara la integridad de misión al ' + fm + '%, por debajo del 70% que esperan los financiadores sociales, y se retiraron.') });
            else if (fm < gr) named.push({ r: 2, t: L('Public guardrail breached: you committed to ' + gr + '% of places for estratos 1 to 3 and ended at ' + fm + '%; funders read a broken commitment as drift.', 'Compromiso público incumplido: te comprometiste al ' + gr + '% de plazas para estratos 1 a 3 y terminaste en ' + fm + '%; los financiadores leen un compromiso roto como deriva.') });
            if (dec.governance === false) named.push({ r: 3, t: L('Governance treated as overhead: skipping the COP 85M reform kept cash in the tightest quarter, but lost the foundation’s renewal and its credibility gain.', 'Gobernanza tratada como gasto: saltarse la reforma de COP 85M guardó caja en el trimestre más ajustado, pero perdió la renovación de la fundación y su ganancia de credibilidad.') });
            var insights = named.map(function(m) { return m.t; });
            var weakImpact = impact <= sustain;
            insights.push(L('The weaker axis set the score: sustainability ' + Math.round(sustain) + ', impact ' + Math.round(impact) + '. The board judges the year on money and mission together, so the overall score is the lower of the two (' + (weakImpact ? 'impact' : 'sustainability') + ' here).',
                'El eje más débil fijó la nota: sostenibilidad ' + Math.round(sustain) + ', impacto ' + Math.round(impact) + '. La junta juzga el año por el dinero y la misión a la vez, así que la nota global es la menor de las dos (aquí, ' + (weakImpact ? 'el impacto' : 'la sostenibilidad') + ').'));
            if (finalCash < 0) insights.push(L('FDI ended the year with negative reserves (COP ' + Math.round(finalCash) + 'M): the income plan did not pay for the cohort it kept.', 'FDI cerró el año con reservas negativas (COP ' + Math.round(finalCash) + 'M): el plan de ingresos no pagó la cohorte que mantuvo.'));
            else insights.push(L('Reserves at year end: COP ' + Math.round(finalCash) + 'M against a quarterly operating cost of about COP ' + Math.round(200 + 1.45 * kept) + 'M.', 'Reservas al cierre del año: COP ' + Math.round(finalCash) + 'M frente a un costo operativo trimestral de unos COP ' + Math.round(200 + 1.45 * kept) + 'M.'));
