            insights = insights.slice(0, 5);
            named.sort(function(a, b) { return a.r - b.r; });
            var turningPoint = named.length ? named[0].t.split(':')[0] + ' (' + L('round ', 'ronda ') + named[0].r + ')'
                : L('No single decision broke the run; the weaker axis set the score.', 'Ninguna decisión aislada rompió la partida; el eje más débil fijó la nota.');
            var questions = [
