        _updatePanels(period) {
            for (var i = 1; i <= 4; i++) {
                var el = document.getElementById('panelR' + i);
                if (el) { if (i === period) el.removeAttribute('hidden'); else el.setAttribute('hidden', ''); }
            }
            var h = document.getElementById('roundHeading');
            if (h && window.mySimulation) h.textContent = window.mySimulation.t('round_heading_r' + Math.min(period, 4));
        }

        _updateAllocTotal(ids, displayId) {
            var total = 0;
            ids.forEach(function(id) { var e = document.getElementById(id); total += (e ? parseInt(e.value) || 0 : 0); });
            var el = document.getElementById(displayId);
            if (el) {
                var ok = (total === 100);
                el.textContent = total + '%' + (ok ? ' ✓' : ' ✗');
                el.style.color = ok ? '#6ee7b7' : '#f87171';
                el.setAttribute('aria-label', total + ' percent allocated' + (ok ? ', valid' : ', must total 100 percent'));
            }
        }

        _updateAllocDisplays() {
            this._updateAllocTotal(['mixGrants', 'mixCorp', 'mixAlianza', 'mixPlace', 'mixIndiv'], 'allocTotalR2');
            this._updateAllocTotal(['mix4Grants', 'mix4Corp', 'mix4Alianza', 'mix4Place', 'mix4Indiv'], 'allocTotalR4');
        }

        _scheduleBriefingRefresh() {
            var self = this;
            setTimeout(function() {
                if (window.mySimulation && window.mySimulation.state) {
                    self._updateBriefing(window.mySimulation.state);
                    self._updatePanels(window.mySimulation.state.currentPeriod || 1);
                }
            }, 350);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;
            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) briefEl.innerHTML = window.mySimulation.t(this.ROUNDS[idx].briefKey);
            this._updatePanels((state.currentPeriod || 1));
        }

